<script lang="ts">
  import { onMount } from "svelte";
  import Button from "$lib/components/Button.svelte";
  import Modal from "$lib/components/Modal.svelte";
  import MoneyInput from "$lib/components/MoneyInput.svelte";
  import { api } from "$lib/api/client";
  import { formatEUR } from "$lib/money";
  import type { Product } from "$lib/types";
  import type { VatRate } from "$lib/vat";

  let services = $state<Product[]>([]); let loading = $state(true); let modalOpen = $state(false); let editingId = $state<number | null>(null); let actionId = $state<number | null>(null); let search = $state(""); let activeFilter = $state<"all" | "active" | "inactive">("active"); let notice = $state(""); let error = $state("");
  let name = $state(""); let code = $state(""); let description = $state(""); let price = $state("0"); let cost = $state("0"); let vat = $state<VatRate>(21);
  const visible = $derived(services.filter((service) => (activeFilter === "all" || (activeFilter === "active" ? service.active : !service.active)) && `${service.name} ${service.sku} ${service.description}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase())));
  function flash(message: string, isError = false) { if (isError) error = message; else notice = message; window.setTimeout(() => isError ? error = "" : notice = "", 3000); }
  async function load() { loading = true; try { services = (await api.listProducts(false)).filter((product) => String(product.category ?? "").trim().toLocaleLowerCase() === "servicio"); } catch (e) { error = e instanceof Error ? e.message : "No se pudieron cargar los servicios"; } finally { loading = false; } }
  function reset() { editingId = null; name = ""; code = ""; description = ""; price = "0"; cost = "0"; vat = 21; }
  function openNew() { reset(); modalOpen = true; }
  function openEdit(service: Product) { editingId = service.id; name = service.name; code = service.sku; description = service.description; price = String(service.price_cents / 100); cost = String(service.cost_cents / 100); vat = service.vat_rate; modalOpen = true; actionId = null; }
  async function save() { if (!name.trim()) { flash("El nombre es obligatorio", true); return; } try { await api.upsertProduct({ id: editingId, sku: code.trim() || `SERV-${Date.now()}`, name: name.trim(), description: description.trim(), category: "Servicio", stock: 0, min_stock: 0, cost_cents: Math.round((Number(cost) || 0) * 100), price_cents: Math.round((Number(price) || 0) * 100), vat_rate: vat, active: true }); await load(); modalOpen = false; flash(editingId ? "Servicio actualizado en PostgreSQL" : "Servicio creado en PostgreSQL"); } catch (e) { flash(e instanceof Error ? e.message : "No se pudo guardar el servicio", true); } }
  async function toggle(service: Product) { actionId = null; try { await api.upsertProduct({ id: service.id, sku: service.sku, name: service.name, description: service.description, category: "Servicio", stock: service.stock, min_stock: service.min_stock, cost_cents: service.cost_cents, price_cents: service.price_cents, vat_rate: service.vat_rate, active: !service.active }); await load(); flash(service.active ? "Servicio archivado en PostgreSQL" : "Servicio reactivado en PostgreSQL"); } catch (e) { flash(e instanceof Error ? e.message : "No se pudo cambiar el estado", true); } }
  onMount(() => { void load(); const close = (event: MouseEvent) => { if (!(event.target as HTMLElement)?.closest(".service-actions, .service-more")) actionId = null; }; document.addEventListener("click", close); return () => document.removeEventListener("click", close); });
</script>

<section class="workspace-page">
  {#if notice}<div class="notice success" role="status">{notice}</div>{/if}{#if error}<div class="notice error" role="alert">{error}</div>{/if}
  <div class="heading"><div><p class="eyebrow">Ventas</p><h2>Servicios <span>ⓘ</span></h2></div><Button onclick={openNew}>Nuevo servicio</Button></div>
  <div class="toolbar"><select class="field" aria-label="Estado" bind:value={activeFilter}><option value="active">Activos</option><option value="all">Todos</option><option value="inactive">Archivados</option></select><div class="search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.6" fill="none" stroke="currentColor" stroke-width="2"/><path d="m16 16 5 5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg><input class="field" placeholder="Buscar servicios…" aria-label="Buscar servicios" bind:value={search} /></div></div>
  {#if loading}<div class="panel state">Cargando servicios desde PostgreSQL…</div>{:else if visible.length === 0}<div class="panel state"><strong>{services.length ? "No hay resultados" : "Todavía no hay servicios"}</strong><span>{services.length ? "Cambia la búsqueda o el estado." : "Crea un servicio para reutilizarlo en presupuestos y facturas."}</span>{#if !services.length}<Button variant="secondary" onclick={openNew}>Crear servicio</Button>{/if}</div>{:else}<div class="panel table"><table><thead><tr><th>Nombre</th><th>Código</th><th>Descripción</th><th class="num">Precio / unidad</th><th class="num">IVA</th><th>Estado</th><th></th></tr></thead><tbody>{#each visible as service (service.id)}<tr><td class="strong">{service.name}</td><td>{service.sku || "—"}</td><td class="description">{service.description || "—"}</td><td class="num">{formatEUR(service.price_cents)}</td><td class="num">{service.vat_rate}%</td><td><span class:archived={!service.active} class="pill">{service.active ? "Activo" : "Archivado"}</span></td><td class="actions"><button class="service-more" aria-label="Acciones" onclick={(event) => { event.stopPropagation(); actionId = actionId === service.id ? null : service.id; }}>⋮</button>{#if actionId === service.id}<div class="service-actions"><button onclick={() => openEdit(service)}>Editar</button><button onclick={() => void toggle(service)}>{service.active ? "Archivar" : "Reactivar"}</button></div>{/if}</td></tr>{/each}</tbody></table></div>{/if}
</section>

<Modal open={modalOpen} title={editingId ? "Editar servicio" : "Nuevo servicio"} size="lg" onclose={() => (modalOpen = false)}><div class="form"><label>Nombre<input class="field" bind:value={name} /></label><label>Código<input class="field" bind:value={code} /></label><label class="wide">Descripción<textarea class="field" rows="4" bind:value={description}></textarea></label><label>Precio / unidad<MoneyInput bind:value={price} ariaLabel="Precio por unidad (€)" /></label><label>Coste / unidad<MoneyInput bind:value={cost} ariaLabel="Coste por unidad (€)" /></label><label>IVA<select class="field" bind:value={vat}><option value={21}>IVA 21%</option><option value={10}>IVA 10%</option><option value={4}>IVA 4%</option><option value={0}>IVA 0%</option></select></label></div><div class="modal-actions"><Button variant="ghost" onclick={() => (modalOpen = false)}>Cancelar</Button><Button onclick={() => void save()}>{editingId ? "Guardar cambios" : "Crear servicio"}</Button></div></Modal>

<style>
  .heading{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:1.25rem}.eyebrow{color:var(--color-muted-dim);font-size:.7rem;text-transform:uppercase;letter-spacing:.18em}.heading h2{margin-top:.25rem;font-size:1.5rem;font-weight:700}.heading h2 span{font-size:.75rem;color:var(--color-muted)}.toolbar{display:flex;align-items:center;gap:.75rem;margin-bottom:1rem;padding:.5rem;border:1px solid var(--color-border);border-radius:.7rem;background:var(--color-obsidian-panel)}.toolbar select{min-width:10rem}.search{position:relative;margin-left:auto;width:min(28rem,42vw)}.search svg{position:absolute;left:.75rem;top:50%;width:1.15rem;transform:translateY(-50%);color:var(--color-muted);pointer-events:none}.search input{width:100%;padding-left:2.5rem}.state{display:flex;min-height:15rem;flex-direction:column;align-items:center;justify-content:center;gap:.65rem;text-align:center;color:var(--color-muted)}.state strong{color:var(--color-text);font-size:1.05rem}.table{overflow:auto;padding:0}.table table{width:100%;min-width:920px;border-collapse:separate;border-spacing:0;text-align:left;font-size:.8rem}.table th{background:var(--color-obsidian-elevated);color:var(--color-muted-dim);font-size:.66rem;text-transform:uppercase;white-space:nowrap}.table th,.table td{padding:.75rem}.table td{border-top:1px solid var(--color-border-soft);white-space:nowrap}.num{text-align:right;font-variant-numeric:tabular-nums}.strong{font-weight:700}.description{max-width:22rem;overflow:hidden;text-overflow:ellipsis}.pill{display:inline-block;padding:.2rem .45rem;border-radius:.3rem;background:rgba(52,211,153,.14);color:#6ee7b7;font-size:.68rem}.pill.archived{background:rgba(148,163,184,.15);color:#cbd5e1}.actions{position:relative;text-align:right}.service-more{border:0;background:transparent;color:var(--color-muted);font-size:1.2rem;cursor:pointer}.service-actions{position:absolute;right:.4rem;top:calc(100% - .1rem);z-index:20;min-width:10rem;padding:.3rem;border:1px solid var(--color-border);border-radius:.55rem;background:var(--color-obsidian-elevated);box-shadow:0 16px 32px rgba(0,0,0,.4)}.service-actions button{display:block;width:100%;padding:.55rem;border:0;border-radius:.3rem;background:transparent;color:var(--color-text);text-align:left;cursor:pointer}.service-actions button:hover{background:var(--color-purple-soft)}.notice{position:fixed;right:1.5rem;top:1.5rem;z-index:10000;padding:.75rem 1rem;border:1px solid;border-radius:.55rem}.notice.success{border-color:rgba(52,211,153,.3);background:rgba(6,78,59,.94);color:#d1fae5}.notice.error{border-color:rgba(244,63,94,.35);background:rgba(76,5,25,.94);color:#ffe4e6}.form{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.form label{display:grid;gap:.35rem;color:var(--color-muted);font-size:.78rem}.form .wide{grid-column:1/-1}.form textarea{resize:vertical}.modal-actions{display:flex;justify-content:flex-end;gap:.5rem;margin-top:1.25rem}@media(max-width:700px){.heading{align-items:flex-start;flex-direction:column}.toolbar{flex-wrap:wrap}.search{order:2;width:100%;margin-left:0}.form{grid-template-columns:1fr}.form .wide{grid-column:auto}}
</style>
